"""Supplementary live probes. Prepare/audit are offline; run requires a source freeze."""

import argparse
import ast
import json
import os
import secrets
import sqlite3
import sys
import threading
import time
import traceback
from datetime import UTC, datetime
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
sys.path.insert(0, str(REPO / "backend" / "scripts" / "phase2"))
sys.path.insert(0, str(REPO / "backend" / "src"))

from audit import canonical, collect, evaluate, reservation_sample, sha
from live_core import (
    MODEL_ID,
    MODEL_PROFILE,
    PROVIDER_ID,
    LiveCore,
    provider_env_from_key,
)
from live_e2e import (
    code_snapshot,
    continuity_snapshot,
    remaining_execution_blocked,
    terminal_composition_failure,
    terminal_planning_failure,
)

VERSION = "supplementary-goal-probes-v25-1"
SUITE = {
    "cases": [
        {"inputs": {"x": 0}, "expected": 1},
        {"inputs": {"x": -4}, "expected": -3},
        {"inputs": {"x": 100}, "expected": 101},
    ]
}
LIMITS = {
    "parallel": {
        "max_nodes": 2,
        "max_members": 2,
        "max_concurrency": 2,
        "max_depth": 1,
        "max_total_tokens": 360000,
        "max_duration_seconds": 600,
        "max_worker_steps": 8,
        "max_worker_tool_calls": 4,
        "max_review_rounds": 3,
    },
    "controlled-defect": {
        "max_nodes": 1,
