    if limits.get("max_members") != 1 or limits.get("max_concurrency") != 1:
        raise ValueError("Original member/concurrency caps changed")
    if set(limits.get("allowed_tools", [])) != {"file_read"}:
        raise ValueError("Team tool scope changed")
    if type(limits.get("max_depth")) is not int or not 0 <= limits["max_depth"] <= 1:
        raise ValueError("Original depth cap changed")
    for key, cap in (
        ("max_steps", 8),
        ("max_tool_calls", 4),
        ("max_duration_seconds", 600),
    ):
        if type(member.get(key)) is not int or not 0 < member[key] <= cap:
            raise ValueError("Original Worker cap changed: " + key)


def oracle_delivery(delivery, source):
    """Check typed values, rather than unrelated number substrings in prose."""
    expected = {
        "release": DOCUMENT["release"],
        **DOCUMENT["checks"],
        "total": DOCUMENT["checks"]["unit"] + DOCUMENT["checks"]["integration"],
        "recommend_shipment": DOCUMENT["checks"]["failed"] == 0
        and sum(DOCUMENT["checks"][key] for key in ("unit", "integration")) >= 15,
        "limitation": DOCUMENT["limitation"],
        "source_path": SOURCE_PATH,
        "source_sha256": source["sha256"],
    }
    candidates = []
    for finding in delivery.get("findings", []):
        try:
            value = json.loads(finding)
        except (ValueError, TypeError):
            continue
        if isinstance(value, dict) and set(value) == set(expected):
            candidates.append(value)
    return len(candidates) == 1 and all(
        type(candidates[0][key]) is type(value) and candidates[0][key] == value
        for key, value in expected.items()
    )


def scoped_rule(text):
    lowered = text.casefold()
    return (
        SOURCE_PATH in text
        and "aster" in lowered
        and "failed" in lowered
        and ("zero" in lowered or "0" in lowered)
        and "unit" in lowered
        and "integration" in lowered
        and ("fifteen" in lowered or "15" in lowered)
    )


def original_memory_item(saved, *, original, first_quest):
    """Accept exact snapshot items whose source is the same original user."""
    item, raw = saved["item"], saved["raw"]
    if not raw or item.get("conflicted") is not False or item.get("omitted"):
        return False
    if (
        item.get("status") != "hypothesis"
        or first_quest not in item.get("related_quest_ids", [])
        or sha(canonical(item).encode()) != saved["item_sha256"]
        or sha(canonical(raw["row"]).encode()) != raw["row_sha256"]
    ):
        return False
    row, kind = raw["row"], raw["table"]
    message_ref = "message:" + original["id"]
    original_hash = sha(canonical(original).encode())
    if kind == "constraint_records":
        return (
            row.get("status") == "active"
            and row.get("quest_id") == first_quest
            and row.get("source_message_id") == original["id"]
            and row.get("source_sha256") == original_hash
            and item.get("source_refs") == [message_ref]
            and row.get("statement") == item.get("statement")
        )
    if kind == "messages":
        return row == original and item.get("source_refs") == [message_ref]
    if kind == "memories":
        return (
            row.get("status") == "hypothesis"
            and json.loads(row["source_refs"])
            == item.get("source_refs")
            == [message_ref]
            and row.get("statement") == item.get("statement")
            and first_quest in json.loads(row["related_quest_ids"])
        )
    # Quest-index items are useful recall but have no single original-message
    # source_refs. The new explicit requirement protocol requires user lineage.
    return False


def recalled_requirements_proof(
    *, original, eligible, selected_ids, records, goal, constraints
):
    """Pure exact binding of model-selected presented items and old-user copies."""
    if (
        not isinstance(selected_ids, list)
        or not selected_ids
        or any(not isinstance(value, str) or not value for value in selected_ids)
        or len(set(selected_ids)) != len(selected_ids)
        or not isinstance(records, list)
        or len(records) != len(selected_ids)
    ):
        return {
            "passed": False,
            "reason": "nonempty_unique_selected_requirements_required",
        }
    by_id = {value["item"]["id"]: value for value in eligible.values()}
    expected, constraint_ids = [], []
    original_hash = sha(canonical(original).encode())
    for selected in selected_ids:
        saved = by_id.get(selected)
        if saved is None:
            return {"passed": False, "reason": "selected_requirement_not_presented"}
        item = saved["item"]
        expected.append(
            {
                "memory_id": selected,
                "statement": item["statement"],
                "source_refs": item["source_refs"],
                "source_hash": item.get("source_hash"),
                "memory_snapshot_sha256": sha(canonical(item).encode()),
                "status": "hypothesis",
                "trust_scope": "recalled source statement only; actual file contents require a fresh read",
            }
        )
        if item["source_refs"] != ["message:" + original["id"]]:
            return {
                "passed": False,
                "reason": "selected_requirement_original_user_mismatch",
            }
        if len(item["statement"].encode()) <= 1024:
            matches = [
                row
                for row in constraints
                if row.get("statement") == item["statement"]
                and row.get("origin") == "pending_model"
                and row.get("source_message_id") == original["id"]
                and row.get("source_sha256") == original_hash
                and row.get("status") == "active"
            ]
            if len(matches) != 1:
                return {
                    "passed": False,
                    "reason": "exact_old_user_hypothesis_copy_missing",
                }
            constraint_ids.append(matches[0]["id"])
    suffix = "\nRecalled requirements (sourced hypotheses):\n" + canonical(expected)
    combined = " ".join(value["statement"] for value in expected)
    if records != expected or not goal.endswith(suffix) or not scoped_rule(combined):
        return {
            "passed": False,
            "reason": "exact_same_source_requirement_conjunction_missing",
        }
    return {
        "passed": True,
        "selected_ids": selected_ids,
        "record_sha256": sha(canonical(records).encode()),
        "constraint_ids": constraint_ids,
    }


def original_source_read(action, spec):
    if (
        action["tool_name"] != "file_read"
        or action["intent_state"] != "succeeded"
        or receipt_errors(action)
    ):
        return False
    workspace = Path(spec["workspace"])
    target = (workspace / SOURCE_PATH).resolve()
    parameters = json.loads(action["parameters_json"])
    path = Path(parameters.get("path", ""))
    selected = path.resolve() if path.is_absolute() else (workspace / path).resolve()
    output = json.loads(action["result_json"])
    content = target.read_bytes()
    return (
        selected == target
        and Path(action["resource_scope"]).resolve() == target
        and output.get("content") == content.decode("utf-8")
        and output.get("sha256") == spec["inputs"][0]["sha256"] == sha(content)
    )


def audit_record(record):
    spec, workspace = record["original_spec"], record["original_spec"]["workspace"]
    failures, tasks = [], []
    quest_ids = record.get("quest_ids", [])
    if len(quest_ids) != 2 or len(set(quest_ids)) != 2:
        return {"passed": False, "failures": ["two_distinct_quests_required"]}
    evidence = collect(workspace, quest_ids[-1])
    if len(evidence["quests"]) != 2 or any(
        q["status"] != "completed" for q in evidence["quests"]
    ):
        failures.append("both_actual_quests_must_complete")
    for index, quest_id in enumerate(quest_ids, 1):
        item = collect(workspace, quest_id)
        passes = independent_passes(item, PROVIDER_ID, MODEL_ID)
        if (
            len(item["workers"]) != 1
            or len(passes) != 1
            or not item["router_completion_notice"]
        ):
            failures.append(
                "actual_current_independent_pass_or_notice_missing:" + quest_id
            )
        if (
            any(receipt_errors(action) for action in item["actions"])
            or item["core_source_errors"]
        ):
            failures.append("invalid_actual_source_receipts:" + quest_id)
        if item["read_only_changes"] != 0:
            failures.append("audit_connection_changed_data")
        reads, source_calls, delivery = [], [], {}
        chain = []
        if len(item["workers"]) == 1:
            worker = item["workers"][0]
            chain, error = worker_exchange_chain(item, worker, PROVIDER_ID, MODEL_ID)
            if error:
                failures.append("actual_worker_model_exchange_unbound:" + quest_id)
            results = [e for e in item["events"] if e["event_type"] == "worker.result"]
            if results:
                result = results[-1]
                delivery = json.loads(result["payload"]["claim"])
                match = passes.get(worker["id"], {})
                review = next(
                    (
                        e
                        for e in item["events"]
                        if e["id"] == match.get("review_event_id")
                    ),
                    None,
                )
                if not review or not _review_link(
                    item, worker, review, result, "PASS", PROVIDER_ID, MODEL_ID
                ):
                    failures.append(
                        "fresh_result_independent_review_unbound:" + quest_id
                    )
            if (
                worker["execution_mode"] != "live"
                or worker["provider_id"] != PROVIDER_ID
                or worker["model_id"] != MODEL_ID
                or worker["steps"] > 8
                or worker["tool_spent"] > 4
                or worker["repairs"] > 2
            ):
                failures.append("original_worker_mode_or_caps_changed:" + quest_id)
        for action in item["actions"]:
            if original_source_read(action, spec):
                reads.append(action["receipt_id"])
                source_calls.extend(
                    {
                        "receipt_id": action["receipt_id"],
                        "gateway_call_id": call["gateway_call_id"],
                        "attempt_id": call["attempt_id"],
                        "assistant_ordinal": call["assistant_ordinal"],
                    }
                    for call in chain
                    for selected in call["selections"]
                    if selected["call_id"] == action["call_id"]
                )
        if not reads:
            failures.append("actual_original_source_read_missing:" + quest_id)
        if index == 2 and not source_calls:
            failures.append("target_model_selected_original_source_read_missing")
        if not oracle_delivery(delivery, spec["inputs"][0]):
            failures.append("exact_current_source_oracle_mismatch:" + quest_id)
        tasks.append(
            {
                "quest_id": quest_id,
                "passes": passes,
                "verified_original_source_receipts": reads,
                "model_selected_source_calls": source_calls,
                "delivery": delivery,
                "read_only_changes": item["read_only_changes"],
            }
        )
    attempts = evidence["attempts"]
    unknown = [
        a["attempt_id"]
        for a in attempts
        if not known_settled(a) or a["input_charged"] < 0 or a["output_charged"] < 0
    ]
    total = sum(
        (a["input_charged"] or 0) + (a["output_charged"] or 0) for a in attempts
    )
    if unknown:
        failures.append("unresolved_usage")
    if not disabled_token_policy(spec, record):
        failures.append("explicit_user_disabled_token_policy_unbound")
    if any(
        a["provider_id"] != PROVIDER_ID
        or a["model_id"] != MODEL_ID
        or a["workspace_id"] != evidence["workspace_id"]
        for a in attempts
    ):
        failures.append("configured_gateway_identity_changed")
    quest_usage = {
        quest_id: sum(
            (a["input_charged"] or 0) + (a["output_charged"] or 0)
            for a in attempts
            if a["quest_id"] == quest_id
        )
        for quest_id in quest_ids
    }
    if evidence["conversation_count"] != 1 or evidence["router"][0][
        "router_session_id"
    ] != record.get("initial_router_identity"):
        failures.append("persistent_router_conversation_changed")
    if sha((Path(workspace) / SOURCE_PATH).read_bytes()) != spec["inputs"][0]["sha256"]:
        failures.append("original_input_changed")
    compaction = record.get("compaction", {})
    if (
        not compaction.get("archive_created")
        or not compaction.get("source_readback_available")
        or not any(
            s["source_id"] == record["source_snapshot_before"]["original_user"]["id"]
            for s in compaction.get("verified_sources", [])
        )
    ):
        failures.append("actual_first_source_compaction_readback_missing")
    with readonly(workspace) as db:
        source_id = record["source_snapshot_before"]["original_user"]["id"]
        archived = db.execute(
            "SELECT a.source_json,a.source_hash,a.capsule_json,a.capsule_hash FROM context_archive_sources s "
            "JOIN context_archives a ON a.id=s.archive_id WHERE s.scope='router' AND s.scope_id='main' AND s.source_id=?",
            (source_id,),
        ).fetchone()
        original = db.execute(
            "SELECT * FROM messages WHERE id=?", (source_id,)
        ).fetchone()
        if not archived or not original:
            failures.append("independent_original_archive_row_missing")
        else:
            sources, capsule = (
                json.loads(archived["source_json"]),
                json.loads(archived["capsule_json"]),
            )
            if (
                sha(canonical(sources).encode()) != archived["source_hash"]
                or sha(canonical(capsule).encode()) != archived["capsule_hash"]
                or not any(
                    s.get("id") == source_id
                    and s.get("hash") == sha(canonical(dict(original)).encode())
                    for s in sources
                )
                or dict(original) != record["source_snapshot_before"]["original_user"]
            ):
                failures.append("independent_original_archive_hash_mismatch")
    restored = ContextService(_ReadOnlyStore(Path(workspace).resolve())).read_source(
        "router", "main", source_id
    )
    if restored != record["source_snapshot_before"]["original_user"]:
        failures.append("independent_original_source_readback_mismatch")
    target = record.get("results", {}).get("task2_message", {}).get("body", {})
    retrieved = (
        target.get("assistant_message", {})
        .get("metadata", {})
        .get("cycle", {})
        .get("retrieved_sources", [])
    )
    before = record.get("source_snapshot_before", {}).get("eligible", {})
    after = source_snapshot(workspace, quest_ids[0])["eligible"]
    used = []
    for ref, value in before.items():
        item = value["item"]
        if ref in retrieved or item["id"] in retrieved:
            current = after.get(ref)
            if (
                current
                and current["item_sha256"] == value["item_sha256"]
                and current["raw"] == value["raw"]
                and sha(canonical(item).encode()) == value["item_sha256"]
                and value["raw"] is not None
                and sha(canonical(value["raw"]["row"]).encode())
                == value["raw"]["row_sha256"]
                and item.get("status") == "hypothesis"
                and quest_ids[0] in item.get("related_quest_ids", [])
                and original_memory_item(
                    value,
                    original=record["source_snapshot_before"]["original_user"],
                    first_quest=quest_ids[0],
                )
            ):
                used.append(
                    {
                        "source_ref": ref,
                        "item_sha256": value["item_sha256"],
                        "raw_sha256": value["raw"]["row_sha256"]
                        if value["raw"]
                        else None,
                        "status": item["status"],
                        "source_type": item.get("source_type"),
                        "source_refs": item["source_refs"],
                        "statement": item["statement"],
                        "item_id": item["id"],
                    }
                )
    if not used or not scoped_rule(" ".join(item["statement"] for item in used)):
        failures.append("original_eligible_hypothesis_not_used_by_target_router")
    sent_at = datetime.fromisoformat(record["task2_sent_at"]).timestamp()
    target_time = datetime.fromisoformat(
        target["assistant_message"]["created_at"]
    ).timestamp()
    semantic = [
        a
        for a in attempts
        if a["purpose"] == "memory_semantic_retrieval"
        and sent_at <= a["created_at"] <= target_time
        and known_settled(a)
        and a["provider_id"] == PROVIDER_ID
        and a["model_id"] == MODEL_ID
        and a["workspace_id"] == evidence["workspace_id"]
    ]
    if not semantic:
        failures.append("target_actual_semantic_recall_attempt_missing")
    router_attempts = [
        a
        for a in attempts
        if a["purpose"] == "router"
        and sent_at <= a["created_at"] <= target_time
        and known_settled(a)
        and a["provider_id"] == PROVIDER_ID
        and a["model_id"] == MODEL_ID
        and a["workspace_id"] == evidence["workspace_id"]
    ]
    if not router_attempts:
        failures.append("target_actual_router_attempt_missing")
    with readonly(workspace) as db:
        second = dict(
            db.execute("SELECT * FROM quests WHERE id=?", (quest_ids[1],)).fetchone()
        )
        metadata = json.loads(second["metadata"])
        source = dict(
            db.execute(
                "SELECT * FROM messages WHERE id=?",
                (metadata["original_request_message_id"],),
            ).fetchone()
        )
        persisted = dict(
            db.execute(
                "SELECT * FROM messages WHERE id=?",
                (target["assistant_message"]["id"],),
            ).fetchone()
        )
        constraints = [
            dict(row)
            for row in db.execute(
                "SELECT * FROM constraint_records WHERE quest_id=? AND status='active'",
                (quest_ids[1],),
            )
        ]
        router_turn = db.execute(
            "SELECT result_json FROM router_turns WHERE request_id=?",
            (spec["run_id"] + "-m2",),
        ).fetchone()
    if (
        source["content"] != spec["second_prompt"]
        or sha(source["content"].encode()) != metadata["original_request_sha256"]
    ):
        failures.append("target_original_prompt_binding_mismatch")
    if (
        SOURCE_PATH in source["content"]
        or RULE in source["content"]
        or DOCUMENT["release"] in source["content"]
        or DOCUMENT["limitation"] in source["content"]
        or any(
            token in source["content"]
            for token in ('"unit":12', '"integration":3', spec["inputs"][0]["sha256"])
        )
    ):
        failures.append("target_prompt_repeated_original_path_rule_or_facts")
    if (
        not router_turn
        or json.loads(router_turn[0]) != target
        or json.loads(persisted["metadata"]).get("cycle", {}).get("retrieved_sources")
        != retrieved
        or target.get("quest_id") != quest_ids[1]
        or target["assistant_message"]["metadata"].get("execution_mode") != "live"
    ):
        failures.append("target_retrieval_not_bound_to_persisted_router_turn")
    if not scoped_rule(second["goal"]):
        failures.append("recovered_reference_rule_missing_from_target_goal")
    selected_ids = target["assistant_message"]["metadata"].get(
        "recalled_requirement_ids", []
    )
    selected_eligible = {
        ref: value
        for ref, value in before.items()
        if value["item"]["id"] in selected_ids
        and original_memory_item(
            value,
            original=record["source_snapshot_before"]["original_user"],
            first_quest=quest_ids[0],
        )
    }
    requirement_proof = recalled_requirements_proof(
        original=record["source_snapshot_before"]["original_user"],
        eligible=selected_eligible,
        selected_ids=selected_ids,
        records=metadata.get("recalled_requirements"),
        goal=second["goal"],
        constraints=constraints,
    )
    if (
        not requirement_proof["passed"]
        or json.loads(persisted["metadata"]).get("recalled_requirement_ids")
        != selected_ids
        or any(selected not in retrieved for selected in selected_ids)
    ):
        failures.append("recovered_rule_not_retained_as_sourced_hypothesis")
    return {
        "passed": not failures,
        "failures": failures,
        "tasks": tasks,
        "used_original_memory": used,
        "retrieved_source_ids": retrieved,
        "target_semantic_attempts": semantic,
        "target_router_attempt_ids": [a["attempt_id"] for a in router_attempts],
        "target_goal": second["goal"],
        "target_delivery": tasks[-1]["delivery"],
        "target_hypothesis_constraint_ids": requirement_proof.get("constraint_ids", []),
        "selected_recalled_requirements": requirement_proof,
        "usage": {
            "known_total_tokens": total,
            "known_tokens_by_quest": quest_usage,
            "unknown_attempt_ids": unknown,
        },
        "read_only_changes": 0,
        "limitations": spec["limitations"],
    }


def run(spec_path, expected_spec, expected_code):
    spec_path = Path(spec_path).resolve()
    spec = json.loads(spec_path.read_text(encoding="utf-8"))
    workspace = Path(spec["workspace"])
    if (
        sha(spec_path.read_bytes()) != expected_spec
        or spec["version"] != VERSION
        or spec["driver_snapshot"] != driver_snapshot()
        or spec["code_snapshot"] != code_snapshot()
        or expected_code != spec["code_snapshot"]["sha256"]
    ):
        raise ValueError("Explicit original spec/driver/frozen code binding mismatch")
    if (
        workspace.resolve() != (spec_path.parent / "workspace")
        or (workspace / "data/forge.sqlite3").exists()
        or (spec_path.parent / "run.json").exists()
    ):
        raise ValueError("Requires fresh isolated unreplayed workspace")
    if (
        tuple(prompts()) != (spec["first_prompt"], spec["second_prompt"])
        or spec["limits_each_quest"] != LIMITS
        or spec.get("token_budget_policy") != TOKEN_BUDGET_POLICY
        or spec.get("token_budget_policy", {}).get("enforced") is not False
        or "global_token_cap" in spec
        or spec["whole_run_seconds"] != 1200
        or sha((workspace / SOURCE_PATH).read_bytes()) != spec["inputs"][0]["sha256"]
    ):
        raise ValueError("Original source/prompt/limits changed")
    record = {
        "started_at": now(),
        "original_spec": spec,
        "spec_sha256": expected_spec,
        "results": {},
        "quest_ids": [],
        "failures": [],
    }
    output = spec_path.parent / "run.json"
    write_json(output, record, new=True)
    core, sensitive = None, []
    started = time.monotonic()
    active_deadline = started + 1140

    def persist():
        encoded = json.dumps(record, ensure_ascii=False, indent=2, allow_nan=False)
        for value in sensitive:
            if value:
                encoded = encoded.replace(value, "[REDACTED]")
        output.write_text(encoded + "\n", encoding="utf-8")

    def timeout(maximum=120):
        remaining = min(started + 1140, active_deadline) - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Original fixed task/run deadline exhausted")
        return max(0.1, min(maximum, remaining))

    def call(label, method, path, payload=None):
        response = core.call(method, path, payload, timeout=timeout())
        record["results"][label] = response
        persist()
        if response["status"] not in {200, 201}:
            raise ValueError("API rejected " + label)
        return response["body"]

    def wait(read, seconds=180):
        deadline = min(started + 1140, active_deadline, time.monotonic() + seconds)
        while time.monotonic() < deadline:
            value = read()
            if value:
                return value
            time.sleep(min(1, max(0, deadline - time.monotonic())))
        raise TimeoutError("Bounded memory-probe stage exhausted")

    try:
        key = os.environ.get("FORGE_PROVIDER_KEY_LIVE_TEST")
        if not key:
            raise ValueError("Credential must exist only in process environment")
        sensitive.append(key)
        core = LiveCore(
            workspace,
            provider_env=provider_env_from_key(key),
            token_limit=None,
            extra_env={"FORGE_ENFORCE_TOKEN_BUDGETS": "false"},
            concurrency=1,
            log=spec_path.parent / "core.log",
        )
        sensitive.append(core.secret)
        record["runtime_settings"] = {
            "token_budgets_enforced": False,
            "model_token_limit": None,
            "model_concurrency_limit": 1,
            "review_max_rounds": 3,
            "worker_lease_seconds": 150,
            "provider_timeout_seconds": 120,
            "provider_max_retries": 0,
            "reasoning_effort": "none",
        }
        core.start(timeout=timeout(30))
        sensitive.append(core.bearer)
        record["initial_router_identity"] = call(
            "conversation", "GET", "/api/conversation"
        )["router"]["router_session_id"]
        call("register", "POST", "/api/models", MODEL_PROFILE)
        call("budget", "GET", "/api/budget")
        for index, prompt in enumerate(prompts(), 1):
            task_started = time.monotonic()
            active_deadline = min(started + 1140, task_started + 540)
            if index == 2:
                record["task2_sent_at"] = now()
            response = call(
                f"task{index}_message",
                "POST",
                "/api/conversation/message",
                {"content": prompt, "request_id": spec["run_id"] + f"-m{index}"},
            )
            quest_id = response.get("quest_id")
            if not quest_id or quest_id in record["quest_ids"]:
                raise ValueError("Router must create two distinct actual Quests")
            record["quest_ids"].append(quest_id)
            if index == 2:
                record["source_snapshot_after_router"] = source_snapshot(
                    workspace, record["quest_ids"][0]
                )

            def plan_ready(quest_id=quest_id, index=index):
                response = core.call(
                    "GET", f"/api/quests/{quest_id}/plan", timeout=timeout(15)
                )
                if response["status"] == 200:
                    return response["body"].get("plan", response["body"])
                terminal = terminal_planning_failure(workspace, quest_id)
                if terminal:
                    record[f"task{index}_planning_failure"] = terminal
                    raise ValueError("Terminal Planner failure")

            plan = wait(plan_ready)
            record[f"task{index}_plan"] = plan
            persist()
            validate_plan(plan, spec, index)
            version = call(
                f"task{index}_before_plan", "GET", f"/api/quests/{quest_id}"
            )["quest"]["version"]
            call(
                f"task{index}_approve_plan",
                "POST",
                f"/api/quests/{quest_id}/plan/approve",
                {
                    "digest": plan["digest"],
                    "plan_revision": plan["revision"],
                    "expected_version": version,
                },
            )

            def team_ready(quest_id=quest_id, index=index):
                response = core.call(
                    "GET", f"/api/quests/{quest_id}/teams", timeout=timeout(15)
                )
                if response["status"] == 200:
                    body = response["body"]
                    for item in (
                        body
                        if isinstance(body, list)
                        else body.get("items", body.get("proposals", []))
                    ):
                        if item.get("status") == "proposed":
                            return item
                terminal = terminal_composition_failure(workspace, quest_id)
                if terminal:
                    record[f"task{index}_composition_failure"] = terminal
                    raise ValueError("Terminal Composer failure")

            team = wait(team_ready)
            record[f"task{index}_team"] = team
            persist()
            validate_team(team)
            version = call(
                f"task{index}_before_team", "GET", f"/api/quests/{quest_id}"
            )["quest"]["version"]
            call(
                f"task{index}_approve_team",
                "POST",
                f"/api/quests/{quest_id}/teams/approve",
                {
                    "plan_revision": team["plan_revision"],
                    "proposal_digest": team["proposal_digest"],
                    "expected_version": version,
                },
            )

            def completed(quest_id=quest_id):
                response = core.call(
                    "GET", f"/api/quests/{quest_id}", timeout=timeout(15)
                )
                if response["status"] != 200:
                    return None
                item = response["body"]
                if item["quest"]["status"] == "completed":
                    return item
                if item["quest"]["status"] in {
                    "failed",
                    "blocked",
                    "cancelled",
                } or remaining_execution_blocked(
                    continuity_snapshot(workspace, quest_id)
                ):
                    raise ValueError("Actual Quest did not complete")

            record[f"task{index}_completion"] = wait(completed, seconds=540)
            wait(
                lambda quest_id=quest_id: collect(workspace, quest_id)[
                    "router_completion_notice"
                ],
                seconds=20,
            )
            record[f"task{index}_duration_seconds"] = time.monotonic() - task_started
            if record[f"task{index}_duration_seconds"] > 600:
                raise ValueError("Original per-task duration exceeded")
            if index == 1:
                record["source_snapshot_pre_compaction"] = source_snapshot(
                    workspace, quest_id
                )
                core.stop()
                record["compaction"] = compact_stopped_core(core)
                record["source_snapshot_before"] = source_snapshot(workspace, quest_id)
                active_deadline = started + 1140
                core.start(timeout=timeout(30))
                sensitive.append(core.bearer)
                if (
                    call("conversation_after_compaction", "GET", "/api/conversation")[
                        "router"
                    ]["router_session_id"]
                    != record["initial_router_identity"]
                ):
                    raise ValueError("Router identity changed")
            persist()
    except BaseException as exc:  # noqa: BLE001 - retain interrupted or failed actual runs
        record["failures"].append(type(exc).__name__ + ":" + str(exc))
    finally:
        if core:
            try:
                core.stop()
            except BaseException as exc:  # noqa: BLE001 - retain shutdown outcome
                record["failures"].append("shutdown_failed:" + type(exc).__name__)
        record["duration_seconds"] = time.monotonic() - started
        record["finished_at"] = now()
        if record["duration_seconds"] > 1200:
            record["failures"].append("original_whole_run_duration_exceeded")
        try:
            record["evidence_files"] = []
            for index, quest_id in enumerate(record["quest_ids"], 1):
                path = spec_path.parent / f"evidence-task{index}.json"
                write_json(path, collect(workspace, quest_id), new=True)
                record["evidence_files"].append(
                    {"path": str(path), "sha256": sha(path.read_bytes())}
                )
            record["audit"] = audit_record(record)
        except BaseException as exc:  # noqa: BLE001 - retain independent audit failure
            record["audit"] = {
                "passed": False,
                "failures": ["audit_failed:" + type(exc).__name__],
            }
        record["final_code_snapshot"] = code_snapshot()
        record["final_driver_snapshot"] = driver_snapshot()
        if (
            record["final_code_snapshot"] != spec["code_snapshot"]
            or record["final_driver_snapshot"] != spec["driver_snapshot"]
        ):
            record["failures"].append("frozen_source_or_driver_changed")
        record["passed"] = not record["failures"] and record["audit"]["passed"]
        persist()
    return {
        "run_path": str(output),
        "passed": record["passed"],
        "failures": record["failures"],
        "audit_failures": record["audit"].get("failures"),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("prepare")
    run_parser = sub.add_parser("run")
    run_parser.add_argument("--prepared", required=True, type=Path)
    run_parser.add_argument("--expect-spec-sha256", required=True)
    run_parser.add_argument("--expect-code-snapshot", required=True)
    audit_parser = sub.add_parser("audit")
    audit_parser.add_argument("--run", required=True, type=Path)
    args = parser.parse_args()
    result = (
        prepare()
        if args.command == "prepare"
        else run(args.prepared, args.expect_spec_sha256, args.expect_code_snapshot)
        if args.command == "run"
        else audit_record(json.loads(args.run.read_text(encoding="utf-8")))
    )
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 1 if result.get("passed") is False else 0


if __name__ == "__main__":
    raise SystemExit(main())

