"""Recheck Git/V27 test preservation; create one V30 report only after explicit disclosure.

Default inspection prints exact discrepancies and writes nothing. No application
imports, Provider/settings access, database access or test execution occurs.
"""

import argparse
import ast
import collections
import copy
import hashlib
import json
import subprocess
import zipfile
from datetime import UTC, datetime
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
REFERENCE = "docs/audit/phase2/preservation-v27.json"
REFERENCE_SHA = "73382430ffd4da7e3445b825143a4ad4281cfac6afd037b90c5a12520105443b"
MANIFEST = "docs/audit/phase2/source-manifest-v27.json"
SNAPSHOT = ".local/phase2/source-snapshot-v27.zip"


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def git(*args, input_bytes=None):
    return subprocess.check_output(["git", *args], cwd=REPO, input=input_bytes)


def functions(source):
    found = {}

    def collect(node, prefix=""):
        for item in ast.iter_child_nodes(node):
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                name = prefix + item.name
                if not isinstance(item, ast.ClassDef) and item.name.startswith("test_"):
                    if name in found:
                        raise ValueError("Duplicate test identity: " + name)
                    found[name] = item
                collect(item, name + ".")
            else:
                collect(item, prefix)

    collect(ast.parse(source))
    return found


def dump(node):
    return ast.dump(node, include_attributes=False)


def assertion_map(node, source):
    counts, texts = collections.Counter(), {}
    for item in ast.walk(node):
        if isinstance(item, ast.Assert):
            key = dump(item)
            counts[key] += 1
            texts[key] = ast.get_source_segment(source, item)
    return counts, texts


def assertions_delta(old, new, before_source, after_source):
    before, old_text = assertion_map(old, before_source)
    after, new_text = assertion_map(new, after_source)
    return {
        "removed": [old_text[key] for key in sorted(before - after) for _ in range((before - after)[key])],
        "added": [new_text[key] for key in sorted(after - before) for _ in range((after - before)[key])],
    }


def normalized_assertions(texts):
    result = collections.Counter()
    for text in texts:
        tree = ast.parse(text)
        if len(tree.body) != 1 or not isinstance(tree.body[0], ast.Assert):
            raise ValueError("Disclosure must contain complete assert statements")
        result[dump(tree.body[0])] += 1
    return result


def same_delta(actual, expected):
    return all(normalized_assertions(actual.get(key, [])) == normalized_assertions(expected.get(key, [])) for key in ("removed", "added"))


def disabling_nodes(source):
    """Include decorator, module-level and body skip/xfail references."""
    return collections.Counter(dump(item) for item in ast.walk(ast.parse(source)) if isinstance(item, ast.Attribute) and item.attr in {"skip", "skipif", "xfail"})


def source_inventory():
    paths = set()
    for folder in ("backend/src", "backend/scripts", "backend/tests"):
        paths.update((REPO / folder).rglob("*.py"))
    paths.update((REPO / "backend/tests").rglob("*.json"))
    paths.update(REPO / name for name in ("backend/pyproject.toml", "backend/requirements-lock.txt"))
    return [{"path": path.relative_to(REPO).as_posix(), "sha256": sha(path.read_bytes()), "bytes": path.stat().st_size} for path in sorted(paths) if "__pycache__" not in path.parts]


def reference(path):
    return {"path": path.relative_to(REPO).as_posix(), "bytes": path.stat().st_size, "sha256": sha(path.read_bytes())}


def explicit_disclosures(path, expected_sha):
    if path is None:
        if expected_sha:
            raise ValueError("Disclosure identity supplied without a file")
        return {}, None
    raw = path.read_bytes()
    if not expected_sha or sha(raw) != expected_sha:
        raise ValueError("Explicit disclosure file requires its caller-supplied exact SHA-256")
    value = json.loads(raw)
    if value.get("schema") != "v30-explicit-test-disclosures-1":
        raise ValueError("Unknown explicit disclosure schema")
    records = value.get("functions", [])
    mapped = {item["identity"]: item for item in records}
    if len(mapped) != len(records):
        raise ValueError("Duplicate explicit disclosure identity")
    for item in records:
        if not isinstance(item.get("review_note"), str) or not item["review_note"].strip():
            raise ValueError("Explicit rationale required: " + item["identity"])
    return mapped, reference(path)


def inspect(extra, extra_ref):
    baseline_raw = (REPO / REFERENCE).read_bytes()
